module restaurant_expected (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] n,\n    input [7:0] g,\n    input [7:0] t,\n    input [7:0] c0,\n    input [7:0] c1,\n    input [7:0] c2,\n    input [7:0] c3,\n    output reg [15:0] sum_occupancy,\n    output reg [15:0] count_sequences,\n    output reg done\n);\n    // State definitions\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT        = 3'd1;\n    localparam [2:0] NEXT_SEQ    = 3'd2;\n    localparam [2:0] SIM_HOUR    = 3'd3;\n    localparam [2:0] UPDATE      = 3'd4;\n    localparam [2:0] DONE_ST     = 3'd5;\n\n    reg [2:0] state, next_state;\n    \n    reg [7:0] sorted_c0, sorted_c1, sorted_c2, sorted_c3;\n    reg [7:0] sequence_cnt;\n    reg [15:0] current_occupancy;\n    reg [2:0] hour;\n    reg [2:0] ti;\n    reg [7:0] group0, group1, group2, group3;\n    reg occupied_0, occupied_1, occupied_2, occupied_3;\n    reg [7:0] temp_seq;\n    reg [15:0] cycle_count;\n\n    // Sorted capacities comparator network\n    always @(*) begin\n        // Bubble-sort steps\n        reg [7:0] st0 = c0;\n        reg [7:0] st1 = c1;\n        reg [7:0] st2 = c2;\n        reg [7:0] st3 = c3;\n        reg [7:0] temp;\n\n        if (st0 > st1) begin temp = st0; st0 = st1; st1 = temp; end\n        if (st1 > st2) begin temp = st1; st1 = st2; st2 = temp; end\n        if (st2 > st3) begin temp = st2; st2 = st3; st3 = temp; end\n\n        if (st0 > st1) begin temp = st0; st0 = st1; st1 = temp; end\n        if (st1 > st2) begin temp = st1; st1 = st2; st2 = temp; end\n\n        if (st0 > st1) begin temp = st0; st0 = st1; st1 = temp; end\n\n        sorted_c0 = st0;\n        sorted_c1 = st1;\n        sorted_c2 = st2;\n        sorted_c3 = st3;\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            sum_occupancy <= 16'd0;\n            count_sequences <= 16'd0;\n            done <= 1'b0;\n            occupied_0 <= 1'b0;\n            occupied_1 <= 1'b0;\n            occupied_2 <= 1'b0;\n            occupied_3 <= 1'b0;\n            sequence_cnt <= 8'd0;\n            current_occupancy <= 16'd0;\n            hour <= 3'd0;\n            ti <= 3'd0;\n            group0 <= 8'd0;\n            group1 <= 8'd0;\n            group2 <= 8'd0;\n            group3 <= 8'd0;\n            cycle_count <= 16'd0;\n        end else begin\n            cycle_count <= cycle_count + 16'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                        sequence_cnt <= 8'd0;\n                        current_occupancy <= 16'd0;\n                    end\n                end\n                \n                INIT: begin\n                    case (t)\n                        8'd1: count_sequences <= g;\n                        8'd2: count_sequences <= g * g;\n                        8'd3: count_sequences <= g * g * g;\n                        8'd4: count_sequences <= g * g * g * g;\n                        default: count_sequences <= 16'd0;\n                    endcase\n                    state <= NEXT_SEQ;\n                end\n\n                NEXT_SEQ: begin\n                    occupied_0 <= 1'b0;\n                    occupied_1 <= 1'b0;\n                    occupied_2 <= 1'b0;\n                    occupied_3 <= 1'b0;\n                    current_occupancy <= 16'd0;\n                    temp_seq <= sequence_cnt;\n                    hour <= 3'd0;\n                    ti <= 3'd0;\n                    state <= SIM_HOUR;\n                    \n                    // Extract group sizes\n                    group0 <= (temp_seq % g) + 8'd1;\n                    temp_seq <= temp_seq / g;\n                    group1 <= (temp_seq % g) + 8'd1;\n                    temp_seq <= temp_seq / g;\n                    group2 <= (temp_seq % g) + 8'd1;\n                    temp_seq <= temp_seq / g;\n                    group3 <= (temp_seq % g) + 8'd1;\n                end\n\n                SIM_HOUR: begin\n                    if (cycle_count > 16'd10000) begin\n                        state <= DONE_ST;\n                    end else if (hour < t) begin\n                        reg [7:0] current_group;\n                        case (hour)\n                            3'd0: current_group = group0;\n                            3'd1: current_group = group1;\n                            3'd2: current_group = group2;\n                            3'd3: current_group = group3;\n                            default: current_group = 8'd0;\n                        endcase\n\n                        case (ti)\n                            3'd0: begin\n                                if (!occupied_0 && (sorted_c0 >= current_group)) begin\n                                    occupied_0 <= 1'b1;\n                                    current_occupancy <= current_occupancy + current_group;\n                                    ti <= 3'd0;\n                                    hour <= hour + 3'd1;\n                                end else begin\n                                    ti <= ti + 3'd1;\n                                end\n                            end\n                            3'd1: begin\n                                if (!occupied_1 && (sorted_c1 >= current_group)) begin\n                                    occupied_1 <= 1'b1;\n                                    current_occupancy <= current_occupancy + current_group;\n                                    ti <= 3'd0;\n                                    hour <= hour + 3'd1;\n                                end else begin\n                                    ti <= ti + 3'd1;\n                                end\n                            end\n                            3'd2: begin\n                                if (!occupied_2 && (sorted_c2 >= current_group)) begin\n                                    occupied_2 <= 1'b1;\n                                    current_occupancy <= current_occupancy + current_group;\n                                    ti <= 3'd0;\n                                    hour <= hour + 3'd1;\n                                end else begin\n                                    ti <= ti + 3'd1;\n                                end\n                            end\n                            3'd3: begin\n                                if (!occupied_3 && (sorted_c3 >= current_group)) begin\n                                    occupied_3 <= 1'b1;\n                                    current_occupancy <= current_occupancy + current_group;\n                                    ti <= 3'd0;\n                                    hour <= hour + 3'd1;\n                                end else begin\n                                    // No available table, advance hour\n                                    hour <= hour + 3'd1;\n                                    ti <= 3'd0;\n                                end\n                            end\n                            default: ti <= 3'd0;\n                        endcase\n                    end else begin\n                        state <= UPDATE;\n                    end\n                end\n\n                UPDATE: begin\n                    sum_occupancy <= sum_occupancy + current_occupancy;\n                    if (sequence_cnt == (count_sequences - 1)) begin\n                        state <= DONE_ST;\n                    end else begin\n                        sequence_cnt <= sequence_cnt + 8'd1;\n                        state <= NEXT_SEQ;\n                    end\n                end\n\n                DONE_ST: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule